  function createProject(){show({title:"Tạo dự án sản xuất",initial:{name:"",productId:products[0]?.id??"",locale:"en-US",creativeId:""},fields:[{name:"name",label:"Tên dự án"},{name:"productId",label:"Sản phẩm",type:"select",options:[{value:"",label:"Chọn sản phẩm"},...products.map(x=>({value:x.id,label:x.data.name}))]},{name:"locale",label:"Ngôn ngữ nội dung",placeholder:"en-US, en-GB…"},{name:"creativeId",label:"Ý tưởng nguồn (nếu có)",type:"select",options:[{value:"",label:"Tạo độc lập"},...records.filter(r=>r.kind==="creative"&&!r.data.archived).map(c=>({value:c.id,label:c.data.name}))],help:"Ý tưởng và sản phẩm phải khớp. Các dòng script được chép thành cảnh nháp, cần duyệt và gắn tham chiếu; không gọi LLM."}],validation:z.object({name:z.string().trim().min(1).max(150),productId:z.string().min(1),locale:z.string().min(2).max(40),creativeId:z.string()}),save:async v=>{const r=await send("create",v,null);route(r.id,"scenes","");}});}
